-- Tenant-scoped workflow tables. Apply once to the configured assetflow_db schema.
CREATE TABLE IF NOT EXISTS buildings (building_id BIGINT AUTO_INCREMENT PRIMARY KEY, company_id BIGINT NOT NULL, building_name VARCHAR(150) NOT NULL, address VARCHAR(500), is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_building_company_name(company_id,building_name), FOREIGN KEY(company_id) REFERENCES companies(company_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS floors (floor_id BIGINT AUTO_INCREMENT PRIMARY KEY, company_id BIGINT NOT NULL, building_id BIGINT NOT NULL, floor_name VARCHAR(100) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(company_id) REFERENCES companies(company_id) ON DELETE CASCADE, FOREIGN KEY(building_id) REFERENCES buildings(building_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS rooms (room_id BIGINT AUTO_INCREMENT PRIMARY KEY, company_id BIGINT NOT NULL, floor_id BIGINT NOT NULL, room_name VARCHAR(100) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(company_id) REFERENCES companies(company_id) ON DELETE CASCADE, FOREIGN KEY(floor_id) REFERENCES floors(floor_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS asset_transfers (transfer_id BIGINT AUTO_INCREMENT PRIMARY KEY, company_id BIGINT NOT NULL, asset_id BIGINT NOT NULL, from_employee_id BIGINT, to_employee_id BIGINT, from_location_id BIGINT, to_location_id BIGINT, requested_by BIGINT, approved_by BIGINT, status VARCHAR(30) NOT NULL DEFAULT 'PENDING', reason VARCHAR(500), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(company_id) REFERENCES companies(company_id) ON DELETE CASCADE, FOREIGN KEY(asset_id) REFERENCES assets(asset_id));
CREATE TABLE IF NOT EXISTS asset_returns (return_id BIGINT AUTO_INCREMENT PRIMARY KEY, company_id BIGINT NOT NULL, asset_id BIGINT NOT NULL, employee_id BIGINT NOT NULL, requested_by BIGINT, approved_by BIGINT, condition_status VARCHAR(30), remarks VARCHAR(500), status VARCHAR(30) NOT NULL DEFAULT 'PENDING', returned_at TIMESTAMP NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(company_id) REFERENCES companies(company_id) ON DELETE CASCADE, FOREIGN KEY(asset_id) REFERENCES assets(asset_id));
CREATE TABLE IF NOT EXISTS invoices (invoice_id BIGINT AUTO_INCREMENT PRIMARY KEY, company_id BIGINT NOT NULL, vendor_id BIGINT, purchase_order_id BIGINT, invoice_number VARCHAR(100) NOT NULL, invoice_date DATE, total_amount DECIMAL(14,2), status VARCHAR(30) NOT NULL DEFAULT 'RECEIVED', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_invoice_company_number(company_id,invoice_number), FOREIGN KEY(company_id) REFERENCES companies(company_id) ON DELETE CASCADE);
